def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast helpers via local loops
    my_coops = 0
    opp_coops = 0
    opp_defects = 0
    my_defects = 0
    cc = 0
    dd = 0
    for (me, opp) in history:
        if me == 'C':
            my_coops += 1
        else:
            my_defects += 1
        if opp == 'C':
            opp_coops += 1
        else:
            opp_defects += 1
        if me == 'C' and opp == 'C':
            cc += 1
        elif me == 'D' and opp == 'D':
            dd += 1

    last_me, last_opp = history[-1]
    opp_rate = opp_coops / n

    # Early game: cooperative, but retaliate once if defected on
    if n < 4:
        if last_opp == 'D' and last_me == 'C':
            return 'D'
        return 'C'

    # Detect defection streak of opponent
    opp_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak_d += 1
        else:
            break

    # My defection streak
    my_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_streak_d += 1
        else:
            break

    # My cooperation streak
    my_streak_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_streak_c += 1
        else:
            break

    # Opponent cooperation streak
    opp_streak_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_streak_c += 1
        else:
            break

    # Near end: exploit reliable cooperators gently
    rounds_left = 100 - n
    if rounds_left <= 2:
        if opp_rate > 0.85 and opp_streak_d == 0:
            # Safe to defect against devoted cooperator
            if my_streak_c >= 3:
                return 'D'
        if last_opp == 'D':
            return 'D'
        if opp_rate > 0.5:
            return 'C'
        return 'D'

    # Opponent almost always defects: defect, with rare probe
    if opp_defects >= (n * 4) // 5 and n >= 6:
        if opp_streak_d >= 6 and rng.random() < 0.06:
            return 'C'
        return 'D'

    # Opponent almost always cooperates: cooperate, but punish betrayal
    if opp_defects <= n // 10 and n >= 5:
        if last_opp == 'D':
            # Retaliate immediately but forgive if only occasional
            if opp_defects == 1 and rng.random() < 0.4:
                return 'C'
            return 'D'
        # Rare probing only when very safe (late)
        if n > 60 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # High cooperation: sustain it, swift targeted retaliation
    if opp_rate > 0.7:
        if last_opp == 'D':
            # Multi-round punishment scales with streak
            if opp_streak_d >= 2:
                return 'D'
            # single defection: retaliate but willing to forgive soon
            if my_streak_d >= 1:
                return 'C'
            return 'D'
        return 'C'

    # Medium-low cooperation: reciprocity with structured forgiveness
    if opp_rate < 0.3:
        # Punish heavily, but break DD cycles occasionally
        if my_streak_d >= 3 and opp_streak_d >= 3:
            if rng.random() < 0.25:
                return 'C'
        if last_opp == 'C':
            return 'C'
        return 'D'

    # Middle: generous tit-for-tat with anti-exploit adjustments
    if last_opp == 'D':
        # If opponent's last defection was isolated, forgive with decent chance
        if n >= 2 and history[-2][1] == 'C':
            if opp_rate > 0.45:
                return 'C'
            return 'D' if rng.random() < 0.7 else 'C'
        # Opponent continuing to defect: keep defecting but probe to break deadlock
        if my_streak_d >= 2 and opp_streak_d >= 2 and rng.random() < 0.3:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if last_me == 'D':
        # We owe cooperation to rebuild
        return 'C'
    # Punish sustained exploitation lightly
    if opp_defects > n // 2 and opp_streak_c >= 2:
        return 'C'
    return 'C'
